import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from './AuthContext';

const SignUp = () => {
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    password: '',
    confirmPassword: '',
    termsAccepted: false
  });
  const [errors, setErrors] = useState({});
  const [strength, setStrength] = useState(0);
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const validatePassword = (password) => {
    const hasUpper = /[A-Z]/.test(password);
    const hasNumber = /\d/.test(password);
    const hasSpecial = /[!@#$%^&*]/.test(password);
    const minLength = password.length >= 8;
    
    return {
      score: (hasUpper + hasNumber + hasSpecial + minLength),
      valid: hasUpper && hasNumber && hasSpecial && minLength
    };
  };

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));

    if (name === 'password') {
      const { score } = validatePassword(value);
      setStrength(score);
    }
  };

  const validateForm = () => {
    const newErrors = {};
    
    if (!formData.fullName.trim()) newErrors.fullName = 'Full name is required';
    if (!formData.email.match(/^\S+@\S+\.\S+$/)) newErrors.email = 'Valid email required';
    if (!formData.password) newErrors.password = 'Password is required';
    if (formData.password !== formData.confirmPassword) newErrors.confirmPassword = 'Passwords must match';
    if (!formData.termsAccepted) newErrors.termsAccepted = 'Accept terms & conditions';
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validateForm()) return;

    setLoading(true);
    
    // Mock API call (replace with real backend)
    try {
      // Simulate API delay
      await new Promise(resolve => setTimeout(resolve, 1500));
      
      const mockUser = {
        id: Date.now(),
        fullName: formData.fullName,
        email: formData.email,
        verified: false
      };
      
      const mockToken = 'mock-jwt-' + Date.now();
      
      login(mockUser, mockToken);
      localStorage.setItem('bookedTickets', JSON.stringify([]));
      
      navigate('/temples');
    } catch (error) {
      setErrors({ submit: 'Signup failed. Try again.' });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-temple-beige to-white flex items-center justify-center py-12 px-4">
      <div className="max-w-md w-full bg-white/90 backdrop-blur-sm rounded-3xl p-10 shadow-2xl border border-gray-100">
        <div className="text-center mb-10">
          <div className="w-20 h-20 bg-gradient-to-br from-temple-gold to-amber-500 rounded-3xl mx-auto mb-6 flex items-center justify-center shadow-2xl">
            <span className="text-3xl">🙏</span>
          </div>
          <h1 className="text-4xl font-bold bg-gradient-to-r from-gray-900 to-temple-dark bg-clip-text text-transparent mb-2">
            Create Account
          </h1>
          <p className="text-gray-600">Join thousands of devotees</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <input
              type="text"
              name="fullName"
              placeholder="Full Name"
              value={formData.fullName}
              onChange={handleInputChange}
              className={`w-full px-4 py-4 border-2 rounded-2xl focus:ring-2 focus:ring-temple-gold focus:border-transparent transition-all ${
                errors.fullName ? 'border-red-300' : 'border-gray-200'
              }`}
            />
            {errors.fullName && <p className="text-red-500 text-sm mt-1">{errors.fullName}</p>}
          </div>

          <div>
            <input
              type="email"
              name="email"
              placeholder="Email Address"
              value={formData.email}
              onChange={handleInputChange}
              className={`w-full px-4 py-4 border-2 rounded-2xl focus:ring-2 focus:ring-temple-gold focus:border-transparent transition-all ${
                errors.email ? 'border-red-300' : 'border-gray-200'
              }`}
            />
            {errors.email && <p className="text-red-500 text-sm mt-1">{errors.email}</p>}
          </div>

          <div>
            <input
              type="password"
              name="password"
              placeholder="Password (8+ chars)"
              value={formData.password}
              onChange={handleInputChange}
              className="w-full px-4 py-4 border-2 border-gray-200 rounded-2xl focus:ring-2 focus:ring-temple-gold focus:border-transparent transition-all"
            />
            <div className="mt-2">
              <div className="flex space-x-2 mb-1">
                {Array.from({ length: 4 }, (_, i) => (
                  <div
                    key={i}
                    className={`w-12 h-1 rounded-full transition-all ${
                      strength > i ? 'bg-emerald-500' : 'bg-gray-300'
                    }`}
                  />
                ))}
              </div>
              <p className={`text-sm ${strength === 4 ? 'text-emerald-600' : 'text-gray-500'}`}>
                {strength < 2 && 'Weak'} {strength === 2 && 'Fair'} 
                {strength === 3 && 'Good'} {strength === 4 && 'Strong'}
              </p>
            </div>
            {errors.password && <p className="text-red-500 text-sm mt-1">{errors.password}</p>}
          </div>

          <div>
            <input
              type="password"
              name="confirmPassword"
              placeholder="Confirm Password"
              value={formData.confirmPassword}
              onChange={handleInputChange}
              className={`w-full px-4 py-4 border-2 rounded-2xl focus:ring-2 focus:ring-temple-gold focus:border-transparent transition-all ${
                errors.confirmPassword ? 'border-red-300' : 'border-gray-200'
              }`}
            />
            {errors.confirmPassword && <p className="text-red-500 text-sm mt-1">{errors.confirmPassword}</p>}
          </div>

          <div className="flex items-center">
            <input
              type="checkbox"
              name="termsAccepted"
              checked={formData.termsAccepted}
              onChange={handleInputChange}
              className="w-5 h-5 text-temple-gold rounded focus:ring-temple-gold"
            />
            <label className="ml-3 text-sm text-gray-700 cursor-pointer">
              I accept <Link href="#" className="text-temple-gold hover:underline">Terms & Conditions</Link> and{' '}
              <Link href="#" className="text-temple-gold hover:underline">Privacy Policy</Link>
            </label>
          </div>
          {errors.termsAccepted && <p className="text-red-500 text-sm">{errors.termsAccepted}</p>}

          {errors.submit && <p className="text-red-500 text-center text-sm p-3 bg-red-50 rounded-2xl">{errors.submit}</p>}

          <button
            type="submit"
            disabled={loading || strength !== 4 || !formData.termsAccepted}
            className="w-full bg-gradient-to-r from-temple-gold to-amber-600 hover:from-temple-gold/90 text-white font-bold py-4 px-8 rounded-3xl shadow-2xl hover:shadow-3xl transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center space-x-2"
          >
            {loading ? (
              <>
                <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                <span>Creating Account...</span>
              </>
            ) : (
              'Create Account'
            )}
          </button>
        </form>

        <div className="text-center mt-8">
          <p className="text-gray-600">
            Already have an account?{' '}
            <Link to="/signin" className="font-bold text-temple-gold hover:underline">
              Sign In →
            </Link>
          </p>
        </div>
      </div>
    </div>
  );
};

export default SignUp;
